#include <map>
#include <iostream>

// Pre-C++11 scenario requiring O(log N) map for standard conformance
void process_data_c98(const std::map<int, std::string>& data) {
    if (data.count(5)) {
        // Lookup complexity is O(log N)
        std::cout << data.at(5) << "\n";
    }
}

